package org.mcrf.client

import org.json.JSONArray
import org.junit.Assert.*
import org.junit.Test

class RoutingDefaultsRussianAppsTest {
    @Test fun pharmacyAndLabBrandsCanBeFoundByRussianName(){mapOf("ru.apteka" to "Аптека.ру","com.invitro.app" to "Инвитро","ru.helix.express" to "Хеликс","ru.mts.smartmed" to "СмартМед").forEach {(pkg,query)->assertTrue(query,RoutingDefaultsRussianApps.matches(RoutingDefaultsRussianApps.byPackage.getValue(pkg),"",query))}}
    @Test fun primarySourcesBindExactPackageAndRejectSpoofedStores(){val pkg="ru.helix";assertTrue(RoutingDefaultsRussianApps.validPrimaryUrl(pkg,"https://play.google.com/store/apps/details?id=ru.helix&hl=ru"));assertTrue(RoutingDefaultsRussianApps.validPrimaryUrl(pkg,"https://play.google.com/store/apps/details?hl=ru&id=ru.helix"));assertTrue(RoutingDefaultsRussianApps.validPrimaryUrl(pkg,"https://www.rustore.ru/catalog/app/ru.helix"));listOf("https://play.google.com/store/apps/details?id=org.other","https://play.google.com/store/apps/details?id=ru.helix&id=ru.helix","https://play.google.com/store/apps/details?id=ru.helix&redirect=bad","https://play.google.com.evil/store/apps/details?id=ru.helix","https://user@play.google.com/store/apps/details?id=ru.helix","http://play.google.com/store/apps/details?id=ru.helix","https://www.rustore.ru/catalog/app/org.other","https://www.rustore.ru.evil/catalog/app/ru.helix","https://example.org/ru.helix").forEach {assertFalse(it,RoutingDefaultsRussianApps.validPrimaryUrl(pkg,it))};assertFalse(RoutingDefaultsRussianApps.validProvenance(pkg,"https://www.rustore.ru/arbitrary/"));assertFalse(RoutingDefaultsRussianApps.validProvenance(pkg,"https://play.google.com/store/apps/details?id=org.other"))}
    @Test fun healthResearchAddsConsumerAppsAndKeepsUnverifiedCandidatesOut(){listOf("ru.apteka","ru.getpharma.eapteka","ru.uteka.app","ru.zdravcity.app","ru.rigla.client.android","com.aptekarsk.pz","com.apteka.sklad","com.platfomni.gorzdrav","com.platfomni.apteka366","com.erkafarm.ozerki","ru.neopharm.neoapp","ru.neopharm.stolichki","com.platfomni.vita","com.platfomni.saas.ma","com.docdoc.docdoc","ru.napopravku","ru.medtochka","ru.mts.smartmed","com.programmisty.emiasapp","com.invitro.app","ru.helix","ru.helix.express").forEach {assertTrue(it,RoutingDefaultsRussianApps.byPackage.containsKey(it))};listOf("pro.ibolit.iBolitPatient.gemotest","ru.medtochka.doctor","ru.smartmed.doctor").forEach {assertFalse(it,RoutingDefaultsRussianApps.byPackage.containsKey(it))};val group=RoutingDefaultsRussianApps.items.groupBy {it.category};assertEquals(14,group.getValue("Аптеки").size);assertEquals(5,group.getValue("Здоровье и медицина").size);assertEquals(3,group.getValue("Медицинские лаборатории").size)}
    @Test fun deliveryLogisticsAndTravelHaveConfirmedServiceIdentities(){listOf("ru.burgerking","ru.kfc.kfc_delivery","com.teremok.keys","com.mobilemedia.tanuki","com.voltmobi.yakitoriya","ru.papajohns.app","com.pizzafabrika.android","ru.mybox.app","com.sushimaster.ru","ru.tokyocity.tokyocity","ru.dostaevsky.android","ru.chibbis","com.broniboy.client","ru.plazius.shokoladnica","ru.perekrestok.app","ru.myauchan.droid","ru.reksoft.okey","com.ru.dixy","ru.av.vkusomania","www.metro.com","com.sebbia.delivery.client","ru.dpd.recipient","ru.dellin.cabinet","ru.pecom.android","ru.baikalsr.lk_android","com.bearsdev.cseapp","ru.s7.android","aero.pobeda.twa","ru.utair.android","pro.bacca.uralairlines","ru.ostrovok.android","ru.sutochno_redesign","com.punicapp.whoosh","ru.urentbike.app","youdrive.today","ru.belkacar.belkacar").forEach {assertTrue(it,RoutingDefaultsRussianApps.byPackage.containsKey(it))};listOf("com.ewt.burger","com.tapston.burgerking","ru.cse.mobile","com.DZDZ.CityDrive","com.YovoGames.BabyTrain").forEach {assertFalse(it,RoutingDefaultsRussianApps.byPackage.containsKey(it))}}
    @Test fun serviceSearchAcceptsBrandSpellingsWithoutDuplicatingPackages(){mapOf("ru.dostaevsky.android" to "Достаевский","ru.kfc.kfc_delivery" to "КФС","com.broniboy.client" to "Бронибой","com.mobilemedia.tanuki" to "Тануки","ru.utair.android" to "Ютэйр","youdrive.today" to "Citydrive","com.bearsdev.cseapp" to "КСЭ").forEach {(pkg,query)->assertTrue(query,RoutingDefaultsRussianApps.matches(RoutingDefaultsRussianApps.byPackage.getValue(pkg),"",query))}}
    @Test fun emptyInstalledSetProducesNoCandidates(){assertTrue(RoutingDefaultsRussianApps.installed(emptySet()).isEmpty())}
    @Test fun repeatedInstalledIdentitiesNeverCreateDuplicateCandidates(){val installed=listOf("ru.yandex.taxi","ru.yandex.taxi","com.yandex.yamb","com.vk.vkvideo","com.uma.musicvk").toSet();val shown=RoutingDefaultsRussianApps.installed(installed);assertEquals(installed,shown.map {it.packageName}.toSet());assertEquals(4,shown.size)}
    @Test fun compatiblePackageApiIncludesVerifiedConsumerAndBusinessYandexApps(){assertEquals(RoutingDefaultsRussianApps.items.map {it.packageName},RoutingDefaults.russianPackages);listOf("ru.yandex.taxi","ru.yandex.yandexmaps","ru.yandex.yandexnavi","ru.yandex.metro","ru.yandex.rasp","ru.yandex.taximeter","com.yandex.browser","ru.yandex.searchplugin","com.yandex.aliceapp","ru.yandex.music","ru.kinopoisk","ru.superapp.plus","ru.yandex.disk","ru.yandex.mail","ru.yandex.telemost","ru.beru.android","ru.foodfox.client","com.yandex.lavka","ru.yandex.mobile.gasstations","com.yandex.mobile.drive","ru.yandex.travel","com.yandex.yamb").forEach {assertTrue(it,RoutingDefaultsRussianApps.byPackage.containsKey(it))}}
@Test fun verifiedCatalogueHasUniqueRealIdentifiersAndSourcePerApp(){val a=RoutingDefaultsRussianApps.items;assertTrue(a.size>=150);assertEquals(a.size,a.map {it.packageName}.toSet().size);a.forEach {RouteRules.validatePackage(it.packageName);assertTrue(it.primaryUrl,RoutingDefaultsRussianApps.validPrimaryUrl(it.packageName,it.primaryUrl));assertTrue(it.provenance,RoutingDefaultsRussianApps.validProvenance(it.packageName,it.provenance));assertEquals(if(it.packageName in setOf("ru.vk.store","com.ertelecom.agent"))"2026-10-17"else"2026-10-14",it.verifiedOn)};assertTrue(a.any {it.packageName=="ru.oneme.app"});assertTrue(a.any {it.packageName=="ru.rzd.pass"});assertTrue(a.any {it.packageName=="ru.rostel"});assertFalse(a.any {it.packageName=="ru.gosuslugi.gosuslugi"})}
    @Test fun coversBankMessengerMarketplaceYandexGovernmentTransportAndOperatorGroups(){val categories=RoutingDefaultsRussianApps.items.groupBy {it.category};assertTrue(categories.getValue("Банки и финансы").size>=29);assertTrue(categories.getValue("Яндекс").size>=30);assertTrue(categories.getValue("VK, OK и Mail").size>=15);assertTrue(categories.getValue("Операторы").size>=6);assertTrue(categories.getValue("Транспорт и поездки").size>=8)}
    @Test fun installedIntersectionNeverGuessesByLabel(){val apps=RoutingDefaultsRussianApps.installed(setOf("ru.oneme.app","org.fake.max","ru.rzd.pass"));assertEquals(setOf("ru.oneme.app","ru.rzd.pass"),apps.map {it.packageName}.toSet())}
    @Test fun nameSearchIncludesBrandAliasAndCategory(){val max=RoutingDefaultsRussianApps.byPackage.getValue("ru.oneme.app");assertTrue(RoutingDefaultsRussianApps.matches(max,"МАКС","MAX"));val rzd=RoutingDefaultsRussianApps.byPackage.getValue("ru.rzd.pass");assertTrue(RoutingDefaultsRussianApps.matches(rzd,"РЖД","транспорт"));assertFalse(RoutingDefaultsRussianApps.matches(rzd,"РЖД","неизвестный банк"))}
    @Test fun selectedAppsBecomeVisibleDirectRuleAndLegacyExclusionsSurvive(){val s=RouteRules.defaults();s.getJSONArray("excludedApps").put("org.personal.direct").put("ru.rzd.pass");val next=RoutingDefaultsRussianAppsPolicy.apply(s,setOf("ru.oneme.app","ru.rzd.pass"),setOf("ru.oneme.app"),false);assertEquals(s.getJSONArray("excludedApps").toString(),next.getJSONArray("excludedApps").toString());val rule=next.getJSONArray("rules").getJSONObject(0);assertEquals("direct",rule.getString("target"));assertEquals("apps",rule.getString("mode"));assertEquals("RU-app · напрямую",rule.getString("name"));assertEquals("ru.oneme.app",RouteRules.matches(rule).getJSONObject(0).getJSONArray("package_name").getString(0));assertEquals(0,s.getJSONArray("rules").length())}
    @Test fun repeatedSelectionUpdatesOneRuleAndEmptySelectionNeverCreatesCatchAll(){val shown=setOf("ru.oneme.app","ru.rzd.pass");val first=RoutingDefaultsRussianAppsPolicy.apply(RouteRules.defaults(),shown,setOf("ru.oneme.app"),false);val second=RoutingDefaultsRussianAppsPolicy.apply(first,shown,setOf("ru.rzd.pass"),false);assertEquals(1,second.getJSONArray("rules").length());assertEquals(setOf("ru.rzd.pass"),RoutingDefaultsRussianAppsPolicy.selected(second));val empty=RoutingDefaultsRussianAppsPolicy.apply(second,shown,emptySet(),false);assertEquals(0,empty.getJSONArray("rules").length())}
    @Test fun unseenExistingSelectionAndForeignRulesArePreserved(){val prior=RoutingDefaultsRussianAppsPolicy.apply(RouteRules.defaults(),setOf("ru.oneme.app","ru.rzd.pass"),setOf("ru.oneme.app","ru.rzd.pass"),false);val foreign=org.json.JSONObject().put("id","foreign").put("name","Personal").put("text","personal.example").put("mode","addresses").put("target","proxy");prior.getJSONArray("rules").put(foreign);val next=RoutingDefaultsRussianAppsPolicy.apply(prior,setOf("ru.oneme.app"),emptySet(),false);assertEquals(setOf("ru.rzd.pass"),RoutingDefaultsRussianAppsPolicy.selected(next));assertEquals(foreign.toString(),next.getJSONArray("rules").getJSONObject(1).toString())}
    @Test fun earlierProxyAppRuleRequiresConsentAndSurvivesBelowDirectRule(){val state=RouteRules.defaults();val foreign=org.json.JSONObject().put("id","foreign").put("name","VPN").put("text","app:ru.oneme.app").put("mode","apps").put("target","proxy");state.getJSONArray("rules").put(foreign);assertEquals(setOf("rule:foreign"),RoutingDefaultsRussianAppsPolicy.conflicts(state,setOf("ru.oneme.app")));val next=RoutingDefaultsRussianAppsPolicy.apply(state,setOf("ru.oneme.app"),setOf("ru.oneme.app"),true);assertEquals(foreign.toString(),next.getJSONArray("rules").getJSONObject(1).toString());assertEquals("direct",next.getJSONArray("rules").getJSONObject(0).getString("target"))}
    @Test(expected=IllegalArgumentException::class) fun legacyIncludeScopeCannotChangeWithoutConsent(){val s=RouteRules.defaults().put("appMode","include");s.getJSONArray("vpnApps").put("org.personal.vpn");RoutingDefaultsRussianAppsPolicy.apply(s,setOf("ru.oneme.app"),setOf("ru.oneme.app"),false)}
    @Test fun emptySelectionRetainsLegacyIncludeScope(){val s=RouteRules.defaults().put("appMode","include");s.getJSONArray("vpnApps").put("org.personal.vpn");val next=RoutingDefaultsRussianAppsPolicy.apply(s,setOf("ru.oneme.app"),emptySet(),false);assertEquals("include",next.getString("appMode"));assertEquals(s.getJSONArray("vpnApps").toString(),next.getJSONArray("vpnApps").toString())}
    @Test(expected=IllegalArgumentException::class) fun foreignIdCollisionDoesNotOverwriteRule(){val s=RouteRules.defaults();s.getJSONArray("rules").put(org.json.JSONObject().put("id",RoutingDefaultsRussianAppsPolicy.RULE_ID).put("name","foreign").put("mode","addresses").put("text","example.org"));RoutingDefaultsRussianAppsPolicy.apply(s,setOf("ru.oneme.app"),setOf("ru.oneme.app"),true)}
    @Test(expected=IllegalArgumentException::class) fun vpnConflictNeedsExplicitConfirmation(){val s=RouteRules.defaults();s.getJSONArray("vpnApps").put("ru.oneme.app");RoutingDefaultsRussianAppsPolicy.apply(s,setOf("ru.oneme.app"),setOf("ru.oneme.app"),false)}
    @Test fun confirmedConflictPreservesOtherVpnChoices(){val s=RouteRules.defaults();s.getJSONArray("vpnApps").put("ru.oneme.app").put("org.personal.vpn");val next=RoutingDefaultsRussianAppsPolicy.apply(s,setOf("ru.oneme.app"),setOf("ru.oneme.app"),true);assertEquals("org.personal.vpn",next.getJSONArray("vpnApps").getString(0))}
    @Test fun lastVpnAppSwitchesModeOnlyWithExplicitConfirmation(){val s=RouteRules.defaults().put("appMode","include");s.getJSONArray("vpnApps").put("ru.oneme.app");val next=RoutingDefaultsRussianAppsPolicy.apply(s,setOf("ru.oneme.app"),setOf("ru.oneme.app"),true);assertEquals("all",next.getString("appMode"));assertEquals(0,next.getJSONArray("vpnApps").length())}
    @Test(expected=IllegalArgumentException::class) fun unseenAppCannotBeAdded(){RoutingDefaultsRussianAppsPolicy.apply(RouteRules.defaults(),setOf("ru.oneme.app"),setOf("ru.rzd.pass"),true)}
    @Test fun pendingCloseFlushRunsOnceAndReadsLatestEdit(){var value="first";val saved=mutableListOf<String>();val pending=RoutingDefaultsPending {saved.add(value)};pending.mark();value="last";pending.mark();pending.flush();pending.flush();assertEquals(listOf("last"),saved)}
    @Test fun quicklyReopenedFormPreservesPriorQueuedChangesToOtherKeys(){val opened=AdvancedDnsConfig.defaults();val current=AdvancedDnsConfig.defaults().put("capacity",4096);val edited=AdvancedDnsConfig.defaults().put("timeout","5s");val merged=RoutingDefaultsEdits.merge(current,opened,edited);assertEquals(4096,merged.getInt("capacity"));assertEquals("5s",merged.getString("timeout"))}
    @Test fun nestedResolverEditsPreserveOtherNewResolverFields(){val opened=AdvancedDnsConfig.defaults();val current=AdvancedDnsConfig.defaults();current.getJSONObject("direct").put("custom","new-value");val edited=AdvancedDnsConfig.defaults();edited.getJSONObject("direct").put("protocol","DoT");val merged=RoutingDefaultsEdits.merge(current,opened,edited);assertEquals("new-value",merged.getJSONObject("direct").getString("custom"));assertEquals("DoT",merged.getJSONObject("direct").getString("protocol"))}
}
